mapper.select:
SELECT  SM.CONTENT
FROM SYS_MESSAGE SM
WHERE SM.MESSAGE_ID =#{messageId}

select sm.content, smr.mobile_phone,sm.message_id,sm.attribute1
  from sys_message             sm,
       sys_message_receiver    smr
 where sm.message_id = smr.message_id
   and sm.message_type = 'SMS'
   and sm.batch_id=#{batchId}
